import { motion } from 'framer-motion';
import { GraduationCap, Award } from 'lucide-react';

export default function About() {
  return (
    <section id="about" className="py-20 relative border-t border-slate-800/50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="mb-16"
        >
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">
            Education & <span className="text-blue-500">Certifications</span>
          </h2>
          <div className="w-20 h-1 bg-blue-500 rounded-full"></div>
        </motion.div>

        <div className="grid md:grid-cols-2 gap-12">
          {/* Education */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: 0.1 }}
          >
            <div className="flex items-center gap-3 mb-6">
              <GraduationCap className="text-blue-500" size={28} />
              <h3 className="text-2xl font-semibold text-white">Education</h3>
            </div>
            <div className="bg-slate-800/50 p-6 rounded-2xl border border-slate-700/50 hover:border-blue-500/30 transition-colors">
              <h4 className="text-xl font-bold text-white mb-2">B.Sc. Computer Science and Engineering</h4>
              <p className="text-blue-400 font-medium mb-2">Erode Sengunthar Engineering College</p>
              <div className="flex justify-between items-center text-slate-400 text-sm">
                <span>Graduated: 2025</span>
                <span className="bg-slate-700/50 px-3 py-1 rounded-full">CGPA: 7.10 / 10</span>
              </div>
            </div>
          </motion.div>

          {/* Certifications */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: 0.2 }}
          >
            <div className="flex items-center gap-3 mb-6">
              <Award className="text-blue-500" size={28} />
              <h3 className="text-2xl font-semibold text-white">Certifications</h3>
            </div>
            <div className="flex flex-col gap-4">
              {[ 
                { title: 'Deloitte Data Analytics Certificate', org: 'Tableau and Data Visualization', year: '2026' },
                { title: 'Infosys Springboard', org: 'Basics of Python', year: '2024' },
                { title: 'NPTEL', org: 'Foundation of Cloud, IoT, Edge, and ML', year: '2024' }
              ].map((cert, index) => (
                <div key={index} className="bg-slate-800/50 p-5 rounded-2xl border border-slate-700/50 hover:border-purple-500/30 transition-colors">
                  <h4 className="font-bold text-white text-lg mb-1">{cert.title}</h4>
                  <div className="flex justify-between items-center text-sm">
                    <span className="text-slate-400">{cert.org}</span>
                    <span className="text-purple-400">{cert.year}</span>
                  </div>
                </div>
              ))}
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

import { motion } from 'framer-motion';
import { Mail, ArrowRight } from 'lucide-react';

export default function Hero() {
  return (
    <section id="hero" className="min-h-screen flex items-center pt-16 relative overflow-hidden">
      {/* Background decoration */}
      <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-purple-500/10 rounded-full blur-3xl pointer-events-none" />

      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
        <div className="max-w-3xl">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <h2 className="text-blue-500 font-medium tracking-wide mb-4">FRONT-END DEVELOPER</h2>
          </motion.div>

          <motion.h1 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="text-5xl sm:text-7xl font-bold tracking-tight text-white mb-6 leading-tight"
          >
            Crafting intuitive <br/>
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-500">
              user experiences.
            </span>
          </motion.h1>

          <motion.p 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="text-lg sm:text-xl text-slate-400 mb-8 leading-relaxed max-w-2xl"
          >
            Hi, I'm Dheena R S. I'm passionate about creative problem-solving and building intuitive, responsive web applications. Eager to contribute technical skills to deliver high-quality, user-centric solutions.
          </motion.p>

          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.3 }}
            className="flex flex-wrap gap-4"
          >
            <a 
              href="#projects" 
              className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-full font-medium flex items-center gap-2 transition-colors"
            >
              View My Work <ArrowRight size={18} />
            </a>
            <a 
              href="mailto:rsdheenacse@gmail.com" 
              className="px-6 py-3 bg-slate-800 hover:bg-slate-700 text-white border border-slate-700 rounded-full font-medium flex items-center gap-2 transition-colors"
            >
              <Mail size={18} /> Let's Connect
            </a>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

import { motion } from 'framer-motion';
import { Github, ExternalLink, Ticket, CloudRain } from 'lucide-react';

const projects = [
  {
    title: 'Movie Ticket Booking',
    description: 'A full-stack movie ticketing application with secure user authentication and account management using Clerk, handling dynamic showtimes and real-time seat availability efficiently.',
    tech: ['MERN Stack', 'Tailwind CSS', 'TMDB API', 'Stripe API', 'Inngest'],
    github: 'https://github.com/Dheena-RS/Quick-Show.git',
    live: 'https://quickshows-xi.vercel.app/',
    icon: <Ticket className="text-purple-500" size={32} />
  },
  {
    title: 'Weather Forecast Dashboard',
    description: 'Dynamic weather dashboard providing users with instant, accurate, real-time forecast data. Features programmatic updates to weather condition icons based on live API responses.',
    tech: ['HTML', 'CSS', 'JavaScript', 'OpenWeatherMap API'],
    github: 'https://github.com/Dheena-RS/Weather-App',
    live: 'https://weather-app-ruby-theta-22.vercel.app/',
    icon: <CloudRain className="text-blue-500" size={32} />
  }
];

export default function Projects() {
  return (
    <section id="projects" className="py-20 relative bg-slate-900/50 border-t border-slate-800/50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="mb-16"
        >
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">
            Featured <span className="text-blue-500">Projects</span>
          </h2>
          <div className="w-20 h-1 bg-blue-500 rounded-full"></div>
        </motion.div>

        <div className="grid md:grid-cols-2 gap-8">
          {projects.map((project, idx) => (
            <motion.div
              key={project.title}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: idx * 0.2 }}
              className="bg-slate-800/40 border border-slate-700/50 rounded-2xl p-8 hover:-translate-y-2 transition-transform duration-300 group"
            >
              <div className="flex justify-between items-start mb-6">
                <div className="bg-slate-700/50 p-4 rounded-xl flex items-center justify-center">
                  {project.icon}
                </div>
                <div className="flex gap-3">
                  <a href={project.github} target="_blank" rel="noreferrer" className="text-slate-400 hover:text-white transition-colors">
                    <Github size={22} />
                  </a>
                  <a href={project.live} target="_blank" rel="noreferrer" className="text-slate-400 hover:text-white transition-colors">
                    <ExternalLink size={22} />
                  </a>
                </div>
              </div>

              <h3 className="text-2xl font-bold text-white mb-3 group-hover:text-blue-400 transition-colors">{project.title}</h3>
              <p className="text-slate-400 mb-6 leading-relaxed">
                {project.description}
              </p>

              <div className="flex flex-wrap gap-2 mt-auto">
                {project.tech.map(tech => (
                  <span key={tech} className="text-xs font-mono text-blue-300 bg-blue-900/20 px-3 py-1 rounded-full border border-blue-800/30">
                    {tech}
                  </span>
                ))}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}

import { motion } from 'framer-motion';

const skillsData = [
  {
    category: 'Programming & Web',
    skills: ['HTML', 'CSS', 'JavaScript', 'Java']
  },
  {
    category: 'Frameworks & Databases',
    skills: ['React', 'Tailwind CSS', 'Bootstrap', 'MongoDB']
  },
  {
    category: 'Tools & Platforms',
    skills: ['Git', 'GitHub', 'VSCode', 'Ubuntu', 'Clerk', 'Excel', 'Power BI']
  }
];

export default function Skills() {
  return (
    <section className="py-20 relative bg-slate-900/50">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="mb-16"
        >
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">
            Technical <span className="text-blue-500">Skills</span>
          </h2>
          <div className="w-20 h-1 bg-blue-500 rounded-full"></div>
        </motion.div>

        <div className="grid md:grid-cols-3 gap-8">
          {skillsData.map((category, idx) => (
            <motion.div
              key={category.category}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: idx * 0.1 }}
              className="bg-slate-800/40 border border-slate-700/50 rounded-2xl p-6"
            >
              <h3 className="text-xl font-bold text-white mb-6 tracking-wide">{category.category}</h3>
              <div className="flex flex-wrap gap-3">
                {category.skills.map((skill) => (
                  <span 
                    key={skill} 
                    className="px-4 py-2 bg-slate-700/30 text-slate-300 rounded-lg text-sm font-medium border border-slate-700/50 hover:border-blue-500/50 hover:text-white transition-colors"
                  >
                    {skill}
                  </span>
                ))}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
